/*
 * Program ID    : SCP0080_GET_PRODUCTION_PLAN_REPORT
 * Description    : PRODUCTION PLAN 조회
 * Program History
 *===================================================================================================
 * Date         In Charge		Description
 *===================================================================================================
 * 2021/09/13   kmj                       OPERATION_ID 조건 추가
 * 2021/09/28   kmj                       VERSION 조건 추가, 2개 버전 MEASURE + GAP 추가, Sub Total
 * 2022/01/25   chaan                     CELL 환산계수 적용
 * 2022/02/15   chaan           V1.31     WPP 기준을 일요일 Cuttoff 로 변경
 * 2022/02/17   chaan           V1.5      CELL 환산계수 적용 -> 전극 관련 보완
 * 2022/02/18   chaan           V1.6      WPP 기준을 일요일 Cuttoff 로 변경 -> ITEM 별 최종 주차를 가져오는 것이 아니라, 조회 기간 중 최종 주차를 찾아 해당 데이터가 없는 ITEM은 0 으로 표시
 * 2022/03/22   khj79                     조회 속도 이슈 발생되어 쿼리 수정 함
 * 2022/07/21   chaan           V1.1.7    필터조건을 SCP 기준으로 통합(Shop Group -> Operation Group), PlantID 필터 조건에서 제외(line 이 이미 plant로 필터링된 상태임)
 * 2022/10/27   chaan           V1.1.8    - 전극(EE, EE_UC) 사업부 일 때 division 에 따른 Operation Group 오류로 divsion 필터 조건 수정
 *                                        - Version Column 추가
 * 2022/11/24   chaan           V1.1.9    데이터 조회오류 확인
 *                                         ~ Version No 추가후 정렬 오류 수정
 * 2022/12/13   chaan           V1.1.10   전극사업부 조회 오류 수정
 * 2022/12/23   chaan           V1.1.11   WPP 조회 오류 수정
                                            - WPP 조회시 키 상관없이 전체 최종 주차만 조회 => PLAN_DATE 기준 키별 자기 주차로 변경
                                            - RESULT 수치 중복 오류 수정
 * 2024-01-08   chaan           V1.1.12   PJ20216994 / LGES Digital SCM 3 Level 가속화를 위한 개선 Phase 2 - UI성능개선 - 조회조건 속도 개선
 */

CREATE PROCEDURE [dbo].[SCP0081_GET_PRODUCTION_PLAN_REPORT]
--CREATE PROCEDURE [dbo].[SCP0081_GET_PRODUCTION_PLAN_REPORT]
    @p_from_yyyymmdd     NVARCHAR(8),
    @p_to_yyyymmdd       NVARCHAR(8),
    @p_division_id       NVARCHAR(1000),
    @p_operation_group   NVARCHAR(1000),
    @p_line_id           NVARCHAR(MAX),
    @p_item_id           NVARCHAR(1000),
    @p_nickname          NVARCHAR(1000),
    @p_user_id           NVARCHAR(30),
    @p_version_id        NVARCHAR(50),
    @p_version_a         NVARCHAR(20),
    @p_version_b         NVARCHAR(20),
    @p_group_column      NVARCHAR(20),
    @debug_mode          NVARCHAR(1) = 'T'
AS
BEGIN
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
    SET NOCOUNT ON;

    --DECLARE @p_from_yyyymmdd    NVARCHAR(8)			= N'20230219';
    --DECLARE @p_to_yyyymmdd      NVARCHAR(8)			= N'20230219';
    --DECLARE @p_division_id      NVARCHAR(1000)		= N'81';
    --DECLARE @p_operation_group     NVARCHAR(1000)	= N'P,A';
    ----DECLARE @p_operation_group     NVARCHAR(1000)	= N'A,E'; --전극
    ----DECLARE @p_plant_id         NVARCHAR(1000)		= N'';
    --DECLARE @p_line_id          NVARCHAR(MAX)		= N'';
    --DECLARE @p_item_id          NVARCHAR(1000)		= N'ACLT1010U-A1-D05';
    --DECLARE @p_nickname         NVARCHAR(1000)		= N'';
    --DECLARE @p_user_id          NVARCHAR(30)		= N'iamarock';
    --DECLARE @p_version_id       NVARCHAR(50)		= N'';
    --DECLARE @p_version_a        NVARCHAR(20)		= N'';
    --DECLARE @p_version_b        NVARCHAR(20)		= N'';
    --DECLARE @p_group_column     NVARCHAR(20)		= N'';
    --DECLARE @debug_mode         NVARCHAR(1)			= N'F';


    DECLARE @v_program_id       NVARCHAR(10)    = 'SCP0081';
    DECLARE @v_sheet_name       NVARCHAR(50)    = 'Production Plan Report';

    DECLARE @V_CNT_USR_MEASURE  INT = 0;
    DECLARE @V_CNT_USR_COLUMN   INT = 0;

    SET @V_CNT_USR_MEASURE = (  SELECT  Count(1)
                                FROM    SCM_MST_TITLESET_USER WITH(NOLOCK)
                                WHERE   1 = 1
                                    AND PROGRAM_ID = @V_PROGRAM_ID
                                    AND SHEET_NAME = @V_SHEET_NAME

		            AA.DIVISION_ID			= FI.DIVISION_ID
		        AND AA.ITEM_ID				= FI.ITEM_ID
		        AND AA.OPERATION_GROUP_ID	= FI.OPERATION_GROUP
			    AND FI.OPERATION_GROUP      = 'E'
	        LEFT JOIN SCM_MST_MODEL_FINAL_ITEM_BOM_V IB WITH(NOLOCK) ON
			        AA.ITEM_ID				= IB.MODEL_ID
		        AND AA.PLANT_ID				= IB.PLANT_ID
		        AND IB.OPERATION_GROUP_ID   = 'A'
	END
--TESGING : OK;
--select * from #TblDynamicPivot_SCP0081_VERSION_T;return;

	/********************************************************************************
	* SUB TOTAL 조회
	********************************************************************************/
	IF OBJECT_ID('tempdb..#TblDynamicPivot_SCP0081_SUB') IS NOT NULL
		DROP TABLE #TblDynamicPivot_SCP0081_SUB

	CREATE TABLE #TblDynamicPivot_SCP0081_SUB
	(
		  DIVISION_ID             NVARCHAR(50)
		, OPERATION_GROUP_ID      NVARCHAR(50)
		, OPERATION_GROUP_NAME    NVARCHAR(50)
		, PLANT_ID                NVARCHAR(50)
		, SCM_SITE_NAME           NVARCHAR(50)
		, OPERATION_ID            NVARCHAR(50)
		, LINE_ID                 NVARCHAR(50)
		, ITEM_ID                 NVARCHAR(50)
		, NICK_NAME               NVARCHAR(150)
		, GROUP_CODE1             NVARCHAR(150)
		, GROUP_CODE2             NVARCHAR(150)
		, GROUP_CODE3             NVARCHAR(150)
		, GROUP_CODE4             NVARCHAR(150)
		, GROUP_CODE5             NVARCHAR(150)
		, MEASURE                 NVARCHAR(50)
		, VERSION_NO              NVARCHAR(50)
		, YYYYMMDD                NVARCHAR(8)
		, QTY                     NUMERIC(20,10)
		, CELL_QTY                NUMERIC(20,10)
		, MEASURE_ORDER_NO        INT
	);

--TESTING : OK
--select * from #TblDynamicPivot_SCP0081_COLUMN;return;

	-- SUB TOTAL 선택IF @p_group_column != ''
	BEGIN
		SET @V_INDEX                = 0;
		DECLARE @V_COLUMN_INDEX INT = 0;

		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
				(
					SELECT  COL
					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			IF @COL = @p_group_column
			BEGIN
				SET @V_COLUMN_INDEX = @V_INDEX;
				BREAK;
			END;

			SET @V_INDEX = @V_INDEX + 1;
		END;

		SET @V_INDEX    = 0;
		SET @mEXEC      = 'INSERT INTO #TblDynamicPivot_SCP0081_SUB ' + CHAR(10);
		SET @mEXEC      = @mEXEC + '( ' + CHAR(10);

		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
			(
				SELECT    COL
				FROM      #TblDynamicPivot_SCP0081_COLUMN
				WHERE     USER_SORT_ORDER_NO = (@V_INDEX + 1)
			);

			-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL = 'SCM_SITE_NAME'
				SET @COL2 = 'PLANT_ID';

			IF (@V_INDEX = 0)
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '    ' + @COL2 + ','
				END

				SET @mEXEC = @mEXEC + '    ' + @COL + CHAR(10);
			END
			ELSE
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '   ,' + @COL2 + CHAR(10);
				END

				SET @mEXEC = @mEXEC + '   ,' + @COL + CHAR(10);
			END

			SET @V_INDEX = @V_INDEX + 1;
		END

		--SET @mEXEC = @mEXEC + '    , MEASURE' + CHAR(10);
		SET @mEXEC     = @mEXEC + '   , YYYYMMDD ' + CHAR(10);
		SET @mEXEC     = @mEXEC + '   , QTY ' + CHAR(10);
		SET @mEXEC     = @mEXEC + '   , CELL_QTY ' + CHAR(10);--chaan
		SET @mEXEC     = @mEXEC + '   , MEASURE_ORDER_NO ' + CHAR(10);
		SET @mEXEC     = @mEXEC + ') ' + CHAR(10);
		SET @V_INDEX   = 0;
		SET @mEXEC     = @mEXEC + 'SELECT' + CHAR(10);

		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
			(
				SELECT  COL
				FROM    #TblDynamicPivot_SCP0081_COLUMN
				WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
			);

			--PRINT @COL;
			--PRINT @V_COLUMN_INDEX;

			-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL =

DD, 20211101) = O.BASIS_YYYYMMDD
SqlFormat end*/

	SET @mEXEC = 'INSERT INTO #TblDynamicPivot_SCP0081_01' +CHAR(10);

	SET @mEXEC = @mEXEC + '(' + CHAR(10);

	SET @V_INDEX = 0;

	WHILE @v_cnt_usr_column > @V_INDEX
	BEGIN
		SET @COL =
			(
				SELECT  COL
				FROM    #TblDynamicPivot_SCP0081_COLUMN
				WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
			);

		-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
		IF @COL = 'OPERATION_GROUP_NAME'
			SET @COL2 = 'OPERATION_GROUP_ID';

		IF @COL = 'SCM_SITE_NAME'
			SET @COL2 = 'PLANT_ID';

		IF (@V_INDEX = 0)
		BEGIN
			IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
			BEGIN
				SET @mEXEC = @mEXEC + '     '+@COL2 +',' +Char(10);
			END

			SET @mEXEC = @mEXEC + '        '+@COL +Char(10);
		END
		ELSE
		BEGIN
			IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
			BEGIN
				SET @mEXEC = @mEXEC + '     ,' + @COL2
			END

			SET @mEXEC = @mEXEC + '        ,' + @COL

		END

		SET @V_INDEX = @V_INDEX + 1;
	END

	--SET @mEXEC = @mEXEC + '                 , MEASURE
	SET @mEXEC = @mEXEC + '                 , YYYYMMDD' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , QTY' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , CELL_QTY' + CHAR(10);--chaan
	SET @mEXEC = @mEXEC + '                 , MEASURE_ORDER_NO' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , YYYYMM' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , ISO_WEEK' + CHAR(10);

	SET @mEXEC = @mEXEC + ')' + CHAR(10);


	SET @V_INDEX    = 0;
	SET @mEXEC        = @mEXEC + 'SELECT' + CHAR(10);

	WHILE @v_cnt_usr_column > @V_INDEX
	BEGIN
		SET @COL =
			(
				SELECT  COL
				FROM    #TblDynamicPivot_SCP0081_COLUMN
				WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
			);

		-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
		IF @COL = 'OPERATION_GROUP_NAME'
			SET @COL2 = 'OPERATION_GROUP_ID';

		IF @COL = 'SCM_SITE_NAME'
			SET @COL2 = 'PLANT_ID';

		IF (@V_INDEX = 0)
		BEGIN
			IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
			BEGIN
				SET @mEXEC = @mEXEC + '     AA.'+@COL2 +','
			END

			SET @mEXEC = @mEXEC + '        AA.'+@COL
		END
		ELSE
		BEGIN
			IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
			BEGIN
				SET @mEXEC = @mEXEC + '     ,AA.'+@COL2
			END

			SET @mEXEC = @mEXEC + '        ,AA.'+@COL
		END

		SET @V_INDEX = @V_INDEX + 1;
	END

	--SET @mEXEC = @mEXEC + '                 , AA.MEASURE
	SET @mEXEC = @mEXEC + '                 , ''D_'' + ISNULL(AA.YYYYMMDD, ' + @p_from_yyyymmdd + ') AS YYYYMMDD' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , ISNULL(AA.QTY, 0) AS QTY' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , ISNULL(AA.CELL_QTY, 0) AS CELL_QTY' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , AA.MEASURE_ORDER_NO' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , O.BASIS_YYYYMM AS YYYYMM' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , RIGHT(O.BASIS_YYYYMM, 4)+O.ISO_WEEK AS ISO_WEEK' + CHAR(10);

	SET @mEXEC = @mEXEC + '                 FROM    (' + CHAR(10);

	-- SELECT    #TblDynamicPivot_SCP0081_02
	SET @V_INDEX = 0;
	SET @mEXEC = @mEXEC + 'SELECT' + CHAR(10);

	WHILE @v_cnt_usr_column > @V_INDEX
	BEGIN
		SET @COL =
			(
				SELECT  COL
				FROM    #TblDynamicPivot_SCP0081_COLUMN
				WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
			);

		-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
		IF @COL = 'OPERATION_GROUP_NAME'
			SET @COL2 = 'OPERATION_GROUP_ID';

		IF @COL = 'SCM_SITE_NAME'
			SET @COL2 = 'PLANT_ID';

		IF (@V_INDEX = 0)
		BEGIN
			IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
			BEGIN
				SET @mEXEC = @mEXEC + '     '+@COL2 +','
			END

			SET @mEXEC = @mEXEC + '        '+@COL
		END
		ELSE
		BEGIN
			IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
			BEGIN
				SET @mEXEC = @mEXEC + '     ,' + @COL2
			END

			SET @mEXEC = @mEXEC + '        ,' + @COL

		END

		SET @V_INDEX = @V_INDEX + 1;

	END

	--SET @mEXEC = @mEXEC + '                 , MEASURE
	SET @mEXEC = @mEXEC + '                 , YYYYMMDD' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , QTY' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 , CELL_QTY' + CHAR(10);--chaan
	SET @mEXEC = @mEXEC + '                 , MEASURE_ORDER_NO' + CHAR(10);

	SET @mEXEC = @mEXEC + '                FROM    #TblDynamicPivot_SCP0081_02' + CHAR(10);

	-- VERSION
	IF @p_version_id != ''
	BEGIN
		SET @mEXEC = @mEXEC + '    UNION ALL' + CHAR(10);

		-- SELECT    #TblDynamicPivot_SCP0081_VERSION_T
		SET @V_INDEX     = 0;
		SET @mEXEC         = @mEXEC + 'SELECT' + CHAR(10);

		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
				(
					SELECT    COL
					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE    USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL = 'SCM_SITE_NAME'
				SET @COL2 = 'PLANT_ID';

			IF (@V_INDEX = 0)
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '     '+@COL2 +','
				END

				SET @mEXEC = @mEXEC + '        '+@COL
			END
			ELSE
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '     ,' + @COL2
				END

				SET @mEXEC = @mEXEC + '        ,' + @COL

			END

			SET @V_INDEX = @V_INDEX + 1;
		END

		--SET @mEXEC = @mEXEC + '                 , MEASURE
		SET @mEXEC = @mEXEC + '                 , YYYYMMDD' + CHAR(10);
		SET @mEXEC = @mEXEC + '                 , QTY' + CHAR(10);
		SET @mEXEC = @mEXEC + '                 , CELL_QTY' + CHAR(10);--chaan
		SET @mEXEC = @mEXEC + '                 , MEASURE_ORDER_NO' + CHAR(10);

		SET @mEXEC = @mEXEC + '    FROM     #TblDynamicPivot_SCP0081_VERSION_T' + CHAR(10);
	END

	-- SUB TOTAL
	IF @p_group_column != ''
	BEGIN
		SET @mEXEC = @mEXEC + '    UNION ALL' + CHAR(10);

		-- SELECT    #TblDynamicPivot_SCP0081_SUB
		SET @V_INDEX = 0;
		SET @mEXEC = @mEXEC + 'SELECT' + CHAR(10);

		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
				(
					SELECT    COL
					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE    USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL = 'SCM_SITE_NAME'
				SET @COL2 = 'PLANT_ID';

			IF (@V_INDEX = 0)
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '     '+@COL2 +','
				END

				SET @mEXEC = @mEXEC + '        '+@COL
			END
			ELSE
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '     ,' + @COL2
				END

				SET @mEXEC = @mEXEC + '        ,' + @COL

			END

			SET @V_INDEX = @V_INDEX + 1;
		END

		--SET @mEXEC = @mEXEC + '                 , MEASURE
		SET @mEXEC = @mEXEC + '                 , YYYYMMDD' + CHAR(10);
		SET @mEXEC = @mEXEC + '                 , QTY' + CHAR(10);
		SET @mEXEC = @mEXEC + '                 , CELL_QTY' + CHAR(10);--chaan
		SET @mEXEC = @mEXEC + '                 , MEASURE_ORDER_NO' + CHAR(10);
		SET @mEXEC = @mEXEC + '            FROM     #TblDynamicPivot_SCP0081_SUB' + CHAR(10);
	END

	SET @mEXEC = @mEXEC + '                 ) AA' + CHAR(10);
	SET @mEXEC = @mEXEC + '                 JOIN SCM_SYS_CALENDAR_M O WITH(NOLOCK) ON ISNULL(AA.YYYYMMDD, ' + @p_from_yyyymmdd + ') = O.BASIS_YYYYMMDD' + CHAR(10);

--TESTING : OK
--select * from #TblDynamicPivot_SCP0081_02;;return;

--TESTING : OK
--exec debug_log @mEXEC, 'T';return;

	EXEC (@mEXEC);

--TESTING : OK
--select * from #TblDynamicPivot_SCP0081_01;return;

--    UPDATE #TblDynamicPivot_SCP0081_01
--    SET
--        VERSION_NO = IIF(MEASURE = 'SCP PLAN_Version A', RTRIM(LTRIM(@p_version_a)

YYYYMMDD  BETWEEN @p_from_yyyymmdd AND @p_to_yyyymmdd
					GROUP BY A.BASIS_YYYYMMDD
				) AS A
		ORDER BY sort_order_no;

		SET @mEXEC = '';
		SET @mEXEC = @mEXEC + 'SELECT' + CHAR(10);

		SET @V_INDEX = 0;

		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
				(
					SELECT  COL
					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			IF (@V_INDEX = 0)
			BEGIN
				SET @mEXEC = @mEXEC + '       ' + @COL + CHAR(10)
			END
			ELSE
			BEGIN
				SET @mEXEC = @mEXEC + '      ,' + @COL + CHAR(10)
			END

			SET @V_INDEX = @V_INDEX + 1;
		END

		SET @mEXEC = @mEXEC + '       ' + @mQry_field    ;
		SET @mEXEC = @mEXEC + 'FROM    (' +CHAR(10);
		SET @mEXEC = @mEXEC + '            SELECT' +CHAR(10);

		SET @V_INDEX = 0;
		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
				(
					SELECT  COL
					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL = 'SCM_SITE_NAME'
				SET @COL2 = 'PLANT_ID';

			IF (@V_INDEX = 0)
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '                    ' + @COL2 + ',' + CHAR(10)
				END

				SET @mEXEC = @mEXEC + '                    ' + @COL + CHAR(10)
			END
			ELSE
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '                   ,' + @COL2 + CHAR(10)
				END

				SET @mEXEC = @mEXEC + '                   ,' + @COL + CHAR(10)
			END

			SET @V_INDEX = @V_INDEX + 1;
		END

		SET @mEXEC = @mEXEC + '                   , MEASURE_ORDER_NO' + CHAR(10);
		SET @mEXEC = @mEXEC + '                   '+@mQry_sum + CHAR(10);
		SET @mEXEC = @mEXEC + '            FROM    #TblDynamicPivot_SCP0081_01' + CHAR(10); --chaan 일요일 cutoff용 임시 테이블로 변경

		-- COLOMN 순서대로 GROUP BY
		SET @V_INDEX = 0;
