					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			-- NAME으로 매핑하는 것은 ID도 같이 GROUP BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL = 'SCM_SITE_NAME'
				SET @COL2 = 'PLANT_ID';

			IF (@V_INDEX = 0)
			BEGIN
				SET @mEXEC = @mEXEC + '            GROUP BY    ';

				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '                        '+@COL2 +',' + CHAR(10);
				END

				SET @mEXEC = @mEXEC + '                        '+@COL + CHAR(10);

			END
			ELSE
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
				BEGIN
					SET @mEXEC = @mEXEC + '                       ,' + @COL2 + CHAR(10);
				END

				SET @mEXEC = @mEXEC + '                       ,' + @COL + CHAR(10);
			END

			SET @V_INDEX = @V_INDEX + 1;
		END

		SET @mEXEC = @mEXEC + '                        ,MEASURE_ORDER_NO' + CHAR(10);
		SET @mEXEC = @mEXEC + '        ) A' + CHAR(10);

		-- COLOMN 순서대로 ORDER BY
		SET @V_INDEX = 0;
		WHILE @v_cnt_usr_column > @V_INDEX
		BEGIN
			SET @COL =
				(
					SELECT  COL
					FROM    #TblDynamicPivot_SCP0081_COLUMN
					WHERE   USER_SORT_ORDER_NO = (@V_INDEX + 1)
				);

			-- NAME으로 매핑하는 것은 ID로 ORDER BY
			IF @COL = 'OPERATION_GROUP_NAME'
				SET @COL2 = 'OPERATION_GROUP_ID';

			IF @COL = 'SCM_SITE_NAME'
				SET @COL2 = 'PLANT_ID';

			-- MEASURE의 경우 MEASURE_ORDER_NO로 ORDER BY
			IF @COL = 'MEASURE'
				SET @COL = 'MEASURE_ORDER_NO';

			IF (@V_INDEX = 0)
			BEGIN
				SET @mEXEC = @mEXEC + 'ORDER BY    ';

				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
					SET @COL = @COL2;

				SET @mEXEC = @mEXEC + '            ' + @COL + CHAR(10);
			END
			ELSE
			BEGIN
				IF @COL = 'OPERATION_GROUP_NAME' OR @COL = 'SCM_SITE_NAME'
					SET @COL = @COL2;

				SET @mEXEC = @mEXEC + '           ,' + @COL + CHAR(10);
			END

			SET @V_INDEX = @V_INDEX + 1;
		END

--TESTING : OK
